@use '../../../styles/variables/colors' as *;

.container {
	position: relative;
	width: 100%;
	overflow-x: auto;
}

.table {
	width: 100%;
	border-collapse: collapse;
	font-size: var(--tile-table-font-size, $text-sm);
	text-align: left;
	caption-side: bottom;
}

.header {
	tr {
		border-bottom: 1px solid var(--tile-table-header-border, $border);
	}
}

.body {
	tr:last-child {
		border-bottom: 0;
	}
}

.footer {
	border-top: 1px solid var(--tile-table-border, $border);
	background-color: var(--tile-table-footer-background, color-mix(in srgb, $muted 50%, transparent));
	font-weight: $font-medium;

	> tr {
		border-bottom-width: 0;
	}
}

.row {
	border-bottom: 1px solid var(--tile-table-border, $border);
	background-color: var(--tile-table-row-background, transparent);
	transition: background-color $transition-fast;

	&:nth-child(even) {
		background-color: var(--tile-table-row-even-background, var(--tile-table-row-background, transparent));
	}

	&:hover {
		background-color: var(--tile-table-row-hover-background, color-mix(in srgb, $muted 50%, transparent));
	}

	&:where(:nth-child(even)):hover {
		background-color: var(--tile-table-row-even-hover-background, color-mix(in srgb, $muted 50%, transparent));
	}

	&:has([aria-expanded='true']) {
		background-color: var(--tile-table-row-expanded-background, color-mix(in srgb, $muted 50%, transparent));
	}

	&[data-state='selected'] {
		background-color: var(--tile-table-row-selected-background, $muted);
	}
}

.head {
	height: 2.5rem;
	padding: var(--tile-table-head-padding, 0 $spacing-2);
	background-color: var(--tile-table-head-background, transparent);
	text-align: left;
	vertical-align: middle;
	font-weight: var(--tile-table-head-weight, $font-medium);
	color: $foreground;
	white-space: nowrap;

	&:has([role='checkbox']) {
		padding-right: 0;
	}

	> [role='checkbox'] {
		transform: translateY(2px);
	}
}

.cell {
	padding: var(--tile-table-cell-padding, $spacing-2);
	vertical-align: middle;
	white-space: nowrap;

	&:has([role='checkbox']) {
		padding-right: 0;
	}

	> [role='checkbox'] {
		transform: translateY(2px);
	}
}

.caption {
	margin-top: $spacing-4;
	font-size: $text-sm;
	color: $muted-foreground;
}
